    @Id var shipmentItemId: UUID? = null,
    var quantity: Int? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "shipment") var shipment: Shipment? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "orderLine") var orderLine: OrderLine? = null
)

@Entity
data class ReturnRequest(
    @Id var returnRequestId: UUID? = null,
    var returnNumber: String? = null,
    var createdAt:  Date? = null,
     @Embedded     @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "refundAmount_amount")),
      AttributeOverride( name = "currency", column = Column(name = "refundAmount_currency"))
    )
    var refundAmount: Money? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "order") var order: Order? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "items") var items:  Set<ReturnItem>? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "refund") var refund: Refund? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "shipment") var shipment: Shipment? = null,
    @Enumerated(EnumType.STRING) var status: ReturnStatus? = null
)

@Entity
data class ReturnItem(
    @Id var returnItemId: UUID? = null,
    var quantity: Int? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "returnRequest") var returnRequest: ReturnRequest? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "orderLine") var orderLine: OrderLine? = null,
    @Enumerated(EnumType.STRING) var reason: ReturnReason? = null,
    @Enumerated(EnumType.STRING) var condition: ReturnItemCondition? = null
)

@Entity
data class Promotion(
    @Id var promotionId: UUID? = null,
    var name: String? = null,
    var code: String? = null,
    var value: java.math.BigDecimal? = null,
    var startDate:  Date? = null,
    var endDate:  Date? = null,
    var asStackable: Boolean? = null,
    var maxRedemptions: Int? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "merchant") var merchant: Merchant? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "channels") var channels:  Set<Channel>? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "applicableProducts") var applicableProducts:  Set<Product>? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "applicableCategories") var applicableCategories:  Set<Category>? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "coupons") var coupons:  Set<Coupon>? = null,
    @Enumerated(EnumType.STRING) var promotionType: PromotionType? = null,
    @Enumerated(EnumType.STRING) var discountType: DiscountType? = null
)

@Entity
data class Coupon(
    @Id var couponId: UUID? = null,
    var code: String? = null,
    var usageLimit: Int? = null,
    var perCustomerLimit: Int? = null,
    var expirationDate:  Date? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "promotion") var promotion: Promotion? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "redemptions") var redemptions:  Set<CouponRedemption>? = null,
    @Enumerated(EnumType.STRING) var status: CouponStatus? = null
)

@Entity
data class CouponRedemption(
    @Id var couponRedemptionId: UUID? = null,
    var redeemedAt:  Date? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "coupon") var coupon: Coupon? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "order") var order: Order? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "customer") var customer: Customer? = null
)

@Entity
data class TaxRule(
    @Id var taxRuleId: UUID? = null,
    var name: String? = null,
    var country: String? = null,
    var region: String? = null,
     @Embedded     @AttributeOverrides(
      AttributeOverride( name = "value", column = Column(name = "rate_value"))
    )
    var rate: Percentage? = null,
    var taxInclusive: Boolean? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "merchant") var merchant: Merchant? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "channels") var channels:  Set<Channel>? = null,
    @Enumerated(EnumType.STRING) var taxClass: TaxClass? = null
)

@Entity
data class ShippingMethod(
    @Id var shippingMethodId: UUID? = null,
    var name: String? = null,
     @Embedded     @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "flatRate_amount")),
      AttributeOverride( name = "currency", column = Column(name = "flatRate_currency"))
    )
    var flatRate: Money? = null,
    var estimatedDays: Int? = null,
    var asActive: Boolean? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "channels") var channels:  Set<Channel>? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "carrierService") var carrierService: CarrierService? = null,
    @Enumerated(EnumType.STRING) var methodType: ShippingMethodType? = null
)

@Entity
data class CarrierService(
    @Id var carrierServiceId: UUID? = null,
    var name: String? = null,
    var code: String? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "shippingMethods") var shippingMethods:  Set<ShippingMethod>? = null,
    @Enumerated(EnumType.STRING) var carrier: Carrier? = null,
    @Enumerated(EnumType.STRING) var serviceLevel: ServiceLevel? = null
)

@Entity
data class Review(
    @Id var reviewId: UUID? = null,
    var rating: Int? = null,
    var title: String? = null,
    var content: String? = null,
    var createdAt:  Date? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "product") var product: Product? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "customer") var customer: Customer? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "order") var order: Order? = null,
    @Enumerated(EnumType.STRING) var status: ReviewStatus? = null
)

@Entity
data class Subscription(
    @Id var subscriptionId: UUID? = null,
    var subscriptionNumber: String? = null,
    var nextBillingDate:  Date? = null,
    var startDate:  Date? = null,
    var endDate:  Date? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "customer") var customer: Customer? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "variant") var variant: ProductVariant? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "paymentProvider") var paymentProvider: PaymentProvider? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "channel") var channel: Channel? = null,
    @Enumerated(EnumType.STRING) var status: SubscriptionStatus? = null,
    @Enumerated(EnumType.STRING) var interval: SubscriptionInterval? = null
)

@Entity
data class PaymentProvider(
    @Id var paymentProviderId: UUID? = null,
    var name: String? = null,
    var enabled: Boolean? = null,
    var merchantAccountId: String? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "merchant") var merchant: Merchant? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "channels") var channels:  Set<Channel>? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "payments") var payments:  Set<Payment>? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "subscriptions") var subscriptions:  Set<Subscription>? = null,
    @Enumerated(EnumType.STRING) var providerType: PaymentProviderType? = null
)

@Entity
data class Invoice(
    @Id var invoiceId: UUID? = null,
    var invoiceNumber: String? = null,
    var issuedDate:  Date? = null,
    var dueDate:  Date? = null,
     @Embedded     @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "total_amount")),
      AttributeOverride( name = "currency", column = Column(name = "total_currency"))
    )
    var total: Money? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "order") var order: Order? = null,
    @Enumerated(EnumType.STRING) var status: InvoiceStatus? = null
)

@Entity
data class GiftCard(
    @Id var giftCardId: UUID? = null,
    var code: String? = null,
     @Embedded     @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "balance_amount")),
      AttributeOverride( name = "currency", column = Column(name = "balance_currency"))
    )
    var balance: Money? = null,
    var expirationDate:  Date? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "customer") var customer: Customer? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "issuedOrder") var issuedOrder: Order? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "redemptions") var redemptions:  Set<GiftCardRedemption>? = null,
    @Enumerated(EnumType.STRING) var status: GiftCardStatus? = null
)

@Entity
data class GiftCardRedemption(
    @Id var giftCardRedemptionId: UUID? = null,
    var redeemedAt:  Date? = null,
     @Embedded     @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "amount_amount")),
      AttributeOverride( name = "currency", column = Column(name = "amount_currency"))
    )
    var amount: Money? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "giftCard") var giftCard: GiftCard? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "order") var order: Order? = null
)

@Entity
data class Payout(
    @Id var payoutId: UUID? = null,
    var payoutNumber: String? = null,
     @Embedded     @AttributeOverrides(
      AttributeOverride( name = "amount", column = Column(name = "amount_amount")),
      AttributeOverride( name = "currency", column = Column(name = "amount_currency"))
    )
    var amount: Money? = null,
    var scheduledDate:  Date? = null,
    var paidDate:  Date? = null,
    @OneToOne(fetch = FetchType.EAGER) @JoinColumn(name = "seller") var seller: Seller? = null,
    @OneToMany(fetch = FetchType.EAGER) @JoinColumn(name = "orders") var orders:  Set<Order>? = null,
    @Enumerated(EnumType.STRING) var status: PayoutStatus? = null
